package de.taxil150.app;
import android.content.*;import android.os.*;import org.json.*;import java.net.*;import java.io.*;import java.util.concurrent.*;
public final class PrayerRepository {
 public static final String WEBSITE="https://namazvakitleri.diyanet.gov.tr/tr-TR/11002/gebetszeit-fur-berlin";
 private final SharedPreferences prefs;private final Runnable changed;private final Handler main=new Handler(Looper.getMainLooper());private ScheduledExecutorService executor;private volatile boolean active;private volatile long generation;private volatile HttpURLConnection current;private volatile JSONObject snapshot=new JSONObject();private volatile String error="";
 public PrayerRepository(Context c,Runnable changed){this.changed=changed;prefs=c.getSharedPreferences("prayers",0);try{snapshot=new JSONObject(prefs.getString("snapshot_v1","{}"));if(snapshot.optJSONObject("days")==null)try(InputStream in=c.getAssets().open("prayer_berlin.json")){snapshot=new JSONObject(read(in));}}catch(Exception ignored){}}
 static String read(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>2000000)throw new IOException("Gebetszeitenantwort zu groß");}return out.toString("UTF-8");}
 public synchronized void start(){if(active)return;active=true;long g=++generation;executor=Executors.newSingleThreadScheduledExecutor();long delay=Math.max(0,21600000-(System.currentTimeMillis()-snapshot.optLong("fetchedAt",0)));executor.scheduleWithFixedDelay(()->fetch(g),delay,3600000,TimeUnit.MILLISECONDS);}
 public synchronized void stop(){active=false;generation++;if(current!=null)current.disconnect();if(executor!=null)executor.shutdownNow();executor=null;}
 private void fetch(long g){if(!active||g!=generation||System.currentTimeMillis()-snapshot.optLong("fetchedAt",0)<21600000)return;HttpURLConnection c=null;try{
 c=(HttpURLConnection)new URL(WEBSITE).openConnection();current=c;c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setUseCaches(false);c.setInstanceFollowRedirects(true);c.setRequestProperty("User-Agent","TaxiMonitor/1.4.1 Android");c.setRequestProperty("Accept","text/html");if(c.getResponseCode()!=200)throw new IOException("Gebetszeiten HTTP "+c.getResponseCode());JSONObject next;try(InputStream in=c.getInputStream()){next=PrayerParser.parse(read(in)).put("fetchedAt",System.currentTimeMillis());}if(!PrayerParser.state(next,"",System.currentTimeMillis()).has("today"))throw new IOException("Keine Zeiten für heute erhalten");if(active&&g==generation){snapshot=next;error="";prefs.edit().putString("snapshot_v1",next.toString()).apply();}
 }catch(Exception e){if(active&&g==generation)error="Aktualisierung derzeit nicht möglich";}finally{if(c!=null)c.disconnect();if(current==c)current=null;if(active&&g==generation)main.post(changed);}}
 public JSONObject state(){try{return PrayerParser.state(snapshot,error,System.currentTimeMillis());}catch(Exception e){return new JSONObject();}}
}
